/* kmicro: a minimal runtime for code generated by the official Kotlin/Native 2.4.21 compiler, single thread, no OS.
 * Contract source: kotlin-native/runtime/src at tag v2.4.21 (Runtime.h/.cpp, Memory.h, TypeInfo.h, Arrays.cpp,
 * Types.cpp, Boxing.cpp, mm/cpp). Layouts below are for 32-bit ARM (pointers 4 bytes). */
#ifndef KMICRO_H
#define KMICRO_H
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define KM_NOTHROW __attribute__((nothrow))
#define KM_ALIGN 8u                                  /* kObjectAlignment (Alignment.hpp) */

typedef struct MemoryState MemoryState;             /* opaque to compiled code; kmicro passes NULL */
typedef struct TypeInfo TypeInfo;

/* Memory.h: every object starts with typeInfoOrMeta_; the low 2 bits are the tag. */
typedef struct ObjHeader { const TypeInfo *typeInfoOrMeta_; } ObjHeader;
typedef struct ArrayHeader { const TypeInfo *typeInfoOrMeta_; uint32_t count_; } ArrayHeader;
enum { KM_TAG_HEAP = 0, KM_TAG_PERMANENT = 1, KM_TAG_STACK = 3, KM_TAG_MASK = 3 };

/* TypeInfo.h (no writable part on non-ObjC targets); checked against %struct.TypeInfo in the generated IR. */
struct TypeInfo {
    const TypeInfo *typeInfo_;
    const void *extendedInfo_;
    uint32_t unused_;
    int32_t instanceSize_;                           /* < 0: array, -element size */
    const TypeInfo *superType_;
    const int32_t *objOffsets_;
    int32_t objOffsetsCount_;
    const TypeInfo *const *implementedInterfaces_;
    int32_t implementedInterfacesCount_;
    int32_t interfaceTableSize_;
    const void *interfaceTable_;
    ObjHeader *packageName_;
    ObjHeader *relativeName_;
    int32_t flags_;
    int32_t classId_;
    const void *associatedObjects;
    void (*processObjectInMark)(void *state, ObjHeader *object);
    uint32_t instanceAlignment_;
};
enum { KM_TF_IMMUTABLE = 1, KM_TF_ACYCLIC = 2, KM_TF_INTERFACE = 4, KM_TF_HAS_FINALIZER = 1 << 6,
       KM_TF_REFLECTION_SHOW_PKG_NAME = 1 << 8, KM_TF_REFLECTION_SHOW_REL_NAME = 1 << 9 };

/* Memory.h FrameOverlay: the shadow-stack frame every function with object locals pushes (EnterFrame). */
typedef struct FrameOverlay { struct FrameOverlay *previous; int32_t parameters; int32_t count; } FrameOverlay;
#define KM_FRAME_OVERLAY_SLOTS ((int)(sizeof(FrameOverlay) / sizeof(ObjHeader *)))

/* Runtime.h: the compiler emits one InitNode per module and registers it from @llvm.global_ctors. */
typedef void (*km_initializer_t)(int mode, MemoryState *memory);
typedef struct InitNode { km_initializer_t init; struct InitNode *next; } InitNode;
enum { KM_ALLOC_THREAD_LOCAL_GLOBALS = 0, KM_INIT_GLOBALS = 1, KM_INIT_THREAD_LOCAL_GLOBALS = 2 };  /* IrToBitcode.kt */
enum { KM_FILE_NOT_INITIALIZED = 0, KM_FILE_BEING_INITIALIZED = 1, KM_FILE_INITIALIZED = 2,
       KM_FILE_FAILED_TO_INITIALIZE = 3 };          /* RuntimePrivate.hpp */

static inline const TypeInfo *km_type_info(const ObjHeader *obj)
{
    const TypeInfo *t = (const TypeInfo *)((uintptr_t)obj->typeInfoOrMeta_ & ~(uintptr_t)KM_TAG_MASK);
    return t->typeInfo_;                             /* a meta object's first word also points at the TypeInfo */
}
static inline unsigned km_tag(const ObjHeader *obj) { return (uintptr_t)obj->typeInfoOrMeta_ & KM_TAG_MASK; }
static inline ObjHeader **km_array_refs(ArrayHeader *a) { return (ObjHeader **)(a + 1); }
static inline void *km_array_data(ArrayHeader *a) { return (void *)(a + 1); }  /* alignUp(8, elem) = 8 */

/* OBJ_GETTER convention (Memory.h): the result also goes to the caller's frame slot. */
static inline ObjHeader *km_return(ObjHeader **slot, ObjHeader *obj) { *slot = obj; return obj; }

/* ---- runtime API for the C side ---- */
void kmicro_init(void);                              /* = Kotlin_initRuntimeIfNeeded for the single thread */
void kmicro_gc(void);                                /* full collection now */
typedef struct { uint32_t heap_bytes, used_bytes, peak_bytes, gc_count, objects_freed, alloc_count; } kmicro_stats_t;
void kmicro_stats(kmicro_stats_t *out);

/* runtime internals shared between files */
extern ObjHeader *kmicro_tls_slots[];
extern int kmicro_tls_slot_count;
ObjHeader *kmicro_alloc_object(const TypeInfo *type, ObjHeader **result);
ObjHeader *kmicro_alloc_array(const TypeInfo *type, int32_t count, ObjHeader **result);

/* Kotlin-side helpers the runtime calls (stdlib RuntimeUtils.kt, exported for the C++ runtime) */
__attribute__((noreturn)) void ThrowArrayIndexOutOfBoundsException(void);
__attribute__((noreturn)) void ThrowOutOfMemoryError(void);
__attribute__((noreturn)) void ThrowIllegalArgumentException(void);
__attribute__((noreturn)) void ThrowFileFailedToInitializeException(ObjHeader *cause);
void checkRangeIndexes(int32_t from, int32_t to, int32_t size);
extern const TypeInfo *theArrayTypeInfo, *theStringTypeInfo, *theCharArrayTypeInfo;

/* platform hooks (the C kernel / the QEMU harness provides them) */
void kmicro_puts(const char *s);
void kmicro_put_int(int32_t v);
__attribute__((noreturn)) void kmicro_panic(const char *what);

/* True inside an exception/interrupt handler (Cortex-M IPSR != 0); always false where there is no IPSR. */
static inline int km_in_interrupt(void)
{
#if defined(__ARM_ARCH_7EM__) || defined(__ARM_ARCH_7M__) || defined(__ARM_ARCH_6M__) || defined(__ARM_ARCH_8M_MAIN__)
    unsigned ipsr;
    __asm volatile("mrs %0, ipsr" : "=r"(ipsr));
    return (ipsr & 0x1FFu) != 0u;
#else
    return 0;
#endif
}

#endif
